CREATE TABLE slice
WITH (format = 'PARQUET', write_compression = 'SNAPPY', external_location = '{loc}/slice/') AS
SELECT
  m.unit_id,
  m.rtype,
  m.id
FROM members AS m
WHERE
  {filter_off}
  OR m.rtype IN ('Patient', 'Encounter')
  OR (
    m.rtype IN ('Observation', 'Condition', 'Procedure', 'ServiceRequest')
    AND EXISTS(
      SELECT
        1
      FROM res_codes AS c
      JOIN vs_codes AS v
        ON v.system = c.system AND v.code = c.code
      WHERE
        c.rtype = m.rtype AND c.id = m.id
    )
  )
  OR (
    m.rtype = 'MedicationAdministration'
