        SELECT
          1
        FROM res_index AS i
        WHERE
          i.rtype = m.rtype AND i.id = m.id AND NOT i.med_ref_id IS NULL
      )
      OR EXISTS(
        SELECT
          1
        FROM res_codes AS c
        JOIN vs_codes AS v
          ON v.system = c.system AND v.code = c.code
        WHERE
          c.rtype = m.rtype AND c.id = m.id
      )
    )
  )
  OR (
    m.rtype = 'Medication'
    AND EXISTS(
      SELECT
        1
      FROM members AS m2
      JOIN res_index AS i2
        ON i2.rtype = m2.rtype AND i2.id = m2.id
      WHERE
        m2.unit_id = m.unit_id
        AND m2.rtype = 'MedicationAdministration'
        AND i2.med_ref_id = m.id
    )
  );

CREATE TABLE slice_hash
WITH (format = 'PARQUET', write_compression = 'SNAPPY', external_location = '{loc}/slice_hash/') AS
SELECT
