              ARRAY_AGG(
                CONCAT(
                  CAST(s.rtype AS VARCHAR),
                  CAST('/' AS VARCHAR),
                  CAST(s.id AS VARCHAR),
                  CAST(':' AS VARCHAR),
                  CAST(LOWER(LOWER(TO_HEX(SHA256(TO_UTF8(r.json))))) AS VARCHAR)
                ) ORDER BY CONCAT(CAST(s.rtype AS VARCHAR), CAST('/' AS VARCHAR), CAST(s.id AS VARCHAR))
